#!/bin/zsh
cd /Users/fillmore/NSF-NCAR/tier3-work/blind-review/REVIEW || exit 1
prompt='You are one of the two reviewers in a blind review. Your working directory holds REVIEW.md, PROMPT.md, four entries A/, B/, C/, D/, scenarios/, and reference/. Read REVIEW.md first and follow it exactly. Review the entries in this order: A, B, C, D; then compare them. Read only inside this working directory: do not read anything elsewhere on this machine, do not use the web, and do not try to identify the agents. Do not build or run any code; the only shell commands you may use are grep, wc, head, tail, and cat, besides the Read, Grep, and Glob tools. Take the time to read each entry thoroughly: its documents, its scans and their data, its prototypes, and its C sources. Your final message must be the complete report in Markdown, in the order REVIEW.md gives, ending with the JSON block it specifies. Nothing but that final message is collected, so put the whole report in it.'
echo "start $(date '+%Y-%m-%d %H:%M:%S')" > /Users/fillmore/NSF-NCAR/tier3-work/blind-review/report-opus.err
env -u CLAUDECODE claude -p --model opus --effort max --tools "Read,Grep,Glob,Bash" --allowedTools "Bash(wc *) Bash(grep *) Bash(head *) Bash(tail *) Bash(cat *)" --disallowedTools "WebSearch WebFetch Agent Edit Write NotebookEdit Bash(git *) Bash(ls *) Bash(find *) Bash(cd *) Bash(python*) Bash(make *) Bash(curl *)" --output-format json "$prompt" > /Users/fillmore/NSF-NCAR/tier3-work/blind-review/report-opus.json 2>> /Users/fillmore/NSF-NCAR/tier3-work/blind-review/report-opus.err
echo "exit $? $(date '+%Y-%m-%d %H:%M:%S')" >> /Users/fillmore/NSF-NCAR/tier3-work/blind-review/report-opus.err
touch /Users/fillmore/NSF-NCAR/tier3-work/blind-review/report-opus.done
